import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import stringToColor from 'flarum/common/utils/stringToColor';
/** A member's avatar, from the arcade's plain user objects. */
export function avatar(person, crown = false) {
  if (!person) return m("span", {
    className: "Avatar InsertCoinAvatar"
  });
  return m("span", {
    className: 'InsertCoinAvatar' + (crown ? ' InsertCoinAvatar--crowned' : '')
  }, person.avatarUrl ? m("img", {
    className: "Avatar",
    src: person.avatarUrl,
    alt: "",
    loading: "lazy",
    decoding: "async"
  }) : m("span", {
    className: "Avatar",
    style: {
      '--avatar-bg': '#' + stringToColor(person.displayName)
    }
  }, person.displayName.charAt(0).toUpperCase()), crown ? m(Icon, {
    name: "fas fa-crown",
    className: "InsertCoinAvatar-crown"
  }) : null);
}

/** Avatar and name, linking to the member's arcade tab. */
export function personLink(person, crown = false) {
  if (!person) return m("span", {
    className: "InsertCoinPerson InsertCoinPerson--gone"
  }, app.translator.trans('core.lib.username.deleted_text'));
  return m(Link, {
    className: "InsertCoinPerson",
    href: app.route('user.arcade', {
      username: person.slug
    })
  }, avatar(person, crown), m("span", {
    className: "InsertCoinPerson-name"
  }, person.displayName));
}
flarum.reg.add('ernestdefoe-insert-coin', 'forum/components/Person', { avatar: avatar,personLink: personLink, });